# -*- coding: utf-8 -*-
import json

W = "https://en.wiktionary.org/wiki/"

data = {
  "pdf_page": 222,
  "book_page": 192,
  "verified_by": "claude-opus-5",
  "verified_on": "2026-09-06",
  "entries": [
    {
      "entry": 0,
      "root": "H.r.m",
      "verdict": "confirmed",
      "modern_form": "Proto-Semitic *ḥ-r-m 'to separate, set apart, declare forbidden/sacred'",
      "note": "The consonantal root ḥ-r-m is genuinely common Semitic, not Arabic-only: Akkadian ḫarāmu 'to separate, dedicate' / ḫarimtu 'hierodule', Hebrew ḥērem 'ban, thing devoted to destruction' with the causative heḥĕrīm, Aramaic aḥrēm 'he banned, excommunicated', Ge'ez (Ethiopic) ḥarama 'he prohibited from common use, devoted to God', Arabic ḥarama / ḥaruma 'to forbid, be forbidden'. Nourai's language label 'Semitic' and gloss 'to forbid' are correct, though the root's semantic core is 'set apart' — whence both 'forbidden' (Arabic ḥarām) and 'sacred' (ḥaram al-šarīf, Hebrew ḥērem 'devoted to YHWH'). The two branches Nourai draws (Arabic, Hebrew) are the two best-attested ones. The only quarrel with the chart is inside individual nodes (see #4, #7, #9), not with the root.",
      "note_fa": "ریشهٔ سه‌حرفی ح‌ر‌م ریشه‌ای سامی مشترک است، نه تنها عربی: در اکدی ḫarāmu «جدا کردن، وقف کردن»، در عبری ḥērem «تحریم، چیزِ وقف‌شده برای نابودی»، در آرامی aḥrēm «تکفیر کرد»، در حبشی (گعز) ḥarama «از استفادهٔ همگانی بازداشت»، و در عربی حَرَمَ/حَرُمَ. معنای بنیادی ریشه «جدا کردن و کنار نهادن» است که از یک سو به «حرام» و از سوی دیگر به «حَرَم/مقدّس» انجامیده است. برچسب زبانیِ «سامی» و معنای «منع کردن» که نورایی آورده درست است؛ اختلاف‌ها در گره‌های جزئی است، نه در خودِ ریشه.",
      "sources": [
        W + "%D8%AD%D8%B1%D9%85",
        W + "%D7%97%D7%A8%D7%9D"
      ],
      "ref_check": [
        {"ref": "FVA:98", "status": "not_checked", "note": "S.M. Nahvi, Farhang-e Vazheha-ye Arabi dar Farsi (1368/1989): no digital copy exists on archive.org, noorlib, ketabnak or elsewhere (refs_online.json: 'RE-SEARCH 2026-09: still no digital copy on any permitted platform'). Not checkable."}
      ],
      "consulted": [
        {"src": "KLN", "where": "KLN_1966.txt line 17630, s.v. 'herem' (1966 2-vol. p. ~754 = the p.723 of Nourai's 1-vol. printing)", "stance": "supports", "note": "'herem, n., Biblical ban, excommunication. — Heb. herem ... rel. to heherim ..., Aram. aharim, 'he banned; excommunicated', Arab. harama, 'he forebade', haruma, 'was forbidden', harim, 'sacred, forbidden', Ethiop. harama ..., Akkad. haramu, 'to dedicate', harimtu, 'a dedicated woman' — i.e. exactly the pan-Semitic root Nourai posits."},
        {"src": "LKT", "where": "no. 819 (LKT.txt line 1981), 'Ar. ḥarām'", "stance": "partial", "note": "Lokotsch gives only the Arabic branch: \"'Verboten'; dasjenige, wozu der Zutritt verboten ist, also der 'Frauenraum' und schließlich 'die Frauen' selbst\" — supports the Arabic side of the root but says nothing about Hebrew/Akkadian."},
        {"src": "BQT", "where": "BQT_v2_pages.txt, grep 'حرام'", "stance": "silent", "note": "Borhan-e Qate' treats only Persian words; the hits (حرامزاده etc.) are compounds, no etymological footnote on the Arabic root itself."}
      ],
      "nodes": [
        {
          "id": 1,
          "lang": "Arabic",
          "words": "harâm; harîm; harem; ihrâm; Moharram",
          "verdict": "confirmed",
          "derivation": "All five are regular derivatives of the Arabic Form-I verb ḥarama 'he forbade' / ḥaruma 'was forbidden, was inviolable'. ḥarām (فَعَال pattern) = 'forbidden, unlawful'; ḥarīm (فَعِيل, 'that which is made inviolable') = the inviolable precinct of a house, hence the women's apartments, whence also the by-form ḥaram 'sacred precinct' (al-Ḥaram al-Šarīf, al-Ḥaramayn = Mecca and Medina); iḥrām is the Form-IV maṣdar of aḥrama 'he made (something) forbidden to himself', used for the pilgrim's state of consecration and, by metonymy, for the two seamless white cloths worn in it; muḥarram is the Form-II passive participle of ḥarrama 'he declared forbidden', hence 'the forbidden (month)', the first month of the Muslim year, in which pre-Islamic Arabia already banned warfare. Nourai's entry 'harem' inside the Arabic box is the European form rather than an Arabic one (Arabic has ḥarīm/ḥaram); that is a presentational slip, not an etymological error.",
          "derivation_fa": "هر پنج واژه مشتق‌های قاعده‌مند فعل عربی حَرَمَ/حَرُمَ «منع کرد، ناروا شد» هستند: «حرام» بر وزن فَعال یعنی ناروا؛ «حریم» بر وزن فَعیل یعنی جای مصون و ممنوع‌الورود و از همین‌جا «حَرَم» شریف و حرمین؛ «إحرام» مصدر باب افعال از أحرم «بر خود حرام کرد» که هم به حالت تقدّس حاجی و هم به جامهٔ دوندوختهٔ او گفته می‌شود؛ و «مُحَرَّم» اسم مفعول باب تفعیل از حرَّم، یعنی ماهی که در آن جنگ حرام است. تنها نکته آنکه صورت harem در جعبهٔ عربی در واقع صورت اروپایی واژه است، نه عربی (عربی حَریم/حَرَم دارد)؛ این لغزشی در نمایش است نه در ریشه‌شناسی. ادعای نورایی درست است.",
          "sources": [W + "%D8%AD%D8%B1%D9%85"],
          "ref_check": [
            {"ref": "KLN:703", "status": "supports", "note": "Klein s.v. 'harem' (KLN_1966.txt line 17209; 1966 2-vol. p. ~734, = p.703 of the 1971 one-volume printing Nourai cites): 'harem, n., women's section in an Oriental house. — Arab. ḥarīm, sacred, forbidden, fr. ḥarama, he forbade, ḥaruma, was forbidden ... Cp. also harmattan, ihram, Muharram.' Klein's ihram entry (line 18694) and Muharram entry (line 24598) give exactly Nourai's other three words."},
            {"ref": "FVA:98", "status": "not_checked", "note": "Nahvi's Farhang-e Vazheha-ye Arabi dar Farsi has no digital copy (see refs_online.json)."}
          ],
